class Solution {
public:
    bool ispalin(string &s,int i,int j)
    {
        while(i<j)
        {
            if(s[i++]!=s[j--])
                return false;
        }
        return true;
    }
    int solve(int i,int j,string s,vector<vector<int>> &dp)
    {
        if(i>=j or ispalin(s,i,j))
            return 0;
        int ans=INT_MAX;
        if(dp[i][j]!=-1)
            return dp[i][j];
        for(int k=i;k<j;k++)
        {
            if(ispalin(s,i,k))
            {
                int temp=solve(k+1,j,s,dp)+1;
                ans=min(ans,temp);
            }
        }
        return dp[i][j]=ans;
    }
    int minCut(string s) {
        int n=s.size();
        vector<vector<int>> dp(n+1,vector<int> (n+1,-1));
        int ans=solve(0,n-1,s,dp);
        return ans;
    }
};
